// The Android notification icons, cut from the brand mark (brand/logo, generated by
// brand/scripts/build_logo.py): the small icon is the white mark on transparent (Android tints
// it), 96 x 96 as expo-notifications asks. Run: node apps/mobile/scripts/notification-icon.mjs
// (set PW_CHROMIUM_PATH to use a browser Playwright didn't download).
import { createRequire } from "node:module";
import { readFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const repo = join(here, "../../..");
const require = createRequire(join(repo, "apps/web/package.json"));
const { chromium } = require("@playwright/test");

const jobs = [
  // [source svg in brand/logo, output in apps/mobile/assets, size, share of the box the mark fills]
  ["sundeck-mark-white.svg", "notification-icon.png", 96, 0.84],
];

const browser = await chromium.launch(
  process.env.PW_CHROMIUM_PATH ? { executablePath: process.env.PW_CHROMIUM_PATH } : {},
);
const page = await browser.newPage({ deviceScaleFactor: 1 });
for (const [src, dest, size, fill] of jobs) {
  const svg = await readFile(join(repo, "brand/logo", src), "utf8");
  const [, , vw, vh] = svg
    .match(/viewBox="([^"]+)"/)[1]
    .split(" ")
    .map(Number);
  // Fit the mark's height (it is taller than wide) inside the box, centered.
  const h = Math.round(size * fill);
  const w = Math.round((h * vw) / vh);
  const sized = svg.replace(/width="[^"]+" height="[^"]+"/, `width="${w}" height="${h}"`);
  await page.setViewportSize({ width: size, height: size });
  await page.setContent(
    `<html><body style="margin:0;background:transparent;width:${size}px;height:${size}px;display:grid;place-items:center">${sized}</body></html>`,
  );
  await page.screenshot({
    path: join(here, "../assets", dest),
    omitBackground: true,
    clip: { x: 0, y: 0, width: size, height: size },
  });
  console.log("wrote", dest, `${size}x${size}`);
}
await browser.close();
